import math
import ast
import operator as op

class Evaluator(ast.NodeVisitor):
    def __init__(self, x):
        self.x = x

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        if isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Sub):
            return left - right
        elif isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Div):
            if right == 0:
                raise ZeroDivisionError
            return left / right
        elif isinstance(node.op, ast.Pow):
            return left ** right
        else:
            raise ValueError("Invalid operator")

    def visit_UnaryOp(self, node):
        operand = self.visit(node.operand)
        if isinstance(node.op, ast.USub):
            return -operand
        else:
            raise ValueError("Invalid unary operator")

    def visit_Num(self, node):
        return node.n

    def visit_NameConstant(self, node):
        if node.value == True:
            return 1
        elif node.value == False:
            return 0
        else:
            raise ValueError("Invalid constant")

    def visit_Call(self, node):
        func_name = self.visit(node.func)
        if func_name == 'sqrt':
            return math.sqrt(self.visit(node.args[0]))
        elif func_name == 'abs':
            return abs(self.visit(node.args[0]))
        elif func_name == 'sin':
            return math.sin(math.radians(self.visit(node.args[0])))
        elif func_name == 'cos':
            return math.cos(math.radians(self.visit(node.args[0]))
        else:
            raise ValueError("Invalid function name")

def evaluate_formula(formula: str, x: float) -> float:
    tree = ast.parse(formula, mode='eval').body
    evaluator = Evaluator(x)
    return evaluator.visit(tree)
